 (186, 3, "do", "Notification restraint wins switchers: notification spam named as the #1 reason for deleting other habit apps", "do", ["13967987039"]),
 (187, 4, "product-rule", "Cosmetic gating is tolerated; functional gating is not — a competitor can charge for skins and give away widgets and habit counts, and this corpus predicts the reaction", "product-rule", ["11016580901","11486217313","14174554457"]),
